  const missing = ["vereinName", "registerangabe", "strasse", "plz", "ort", "standardEmail", "kontoinhaber", "bankname", "iban", "bic", "dokumentOrt"].find((key) => !snapshot[key as keyof ClubConfigurationSnapshot]);
